                } // if $obj4 already loaded

                // Add the $obj1 (ExpedienteReglas) to the collection in $obj4 (TipoExpedienteReglas)
                $obj4->addExpedienteReglas($obj1);

            } // if joined row is not null

                // Add objects for joined Modulo rows

                $key5 = ModuloPeer::getPrimaryKeyHashFromRow($row, $startcol5);
                if ($key5 !== null) {
                    $obj5 = ModuloPeer::getInstanceFromPool($key5);
                    if (!$obj5) {
    
                        $cls = ModuloPeer::getOMClass();

                    $obj5 = new $cls();
                    $obj5->hydrate($row, $startcol5);
                    ModuloPeer::addInstanceToPool($obj5, $key5);
                } // if $obj5 already loaded

                // Add the $obj1 (ExpedienteReglas) to the collection in $obj5 (Modulo)
                $obj5->addExpedienteReglas($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

