            throw new PropelException('Cannot insert a value for auto-increment primary key ('.ExpedienteReglasPeer::EXPEDIENTEREGLAS_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ExpedienteReglasPeer::EXPEDIENTEREGLAS_ID);


        // Set the correct dbName
        $criteria->setDbName(ExpedienteReglasPeer::DATABASE_NAME);

        try {
            // use transaction because $criteria could contain info
